import{_ as t,o,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"OCSE - OpenCubeOS Setup Environment: architecture and responsibilities","description":"","frontmatter":{},"headers":[],"relativePath":"components/ocse/ocse-architecture.md","filePath":"components/ocse/ocse-architecture.md"}'),i={name:"components/ocse/ocse-architecture.md"};function n(r,e,s,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="ocse-opencubeos-setup-environment-architecture-and-responsibilities" tabindex="-1">OCSE - OpenCubeOS Setup Environment: architecture and responsibilities <a class="header-anchor" href="#ocse-opencubeos-setup-environment-architecture-and-responsibilities" aria-label="Permalink to &quot;OCSE - OpenCubeOS Setup Environment: architecture and responsibilities&quot;">​</a></h1><p>OCSE is the operating-system <strong>installer environment</strong> of Open Cube OS: a small, freestanding kernel that boots from the install media and turns a blank machine into a bootable Open Cube OS system. It lives in its own source tree (<code>ocse/</code>), links with its own linker script (<code>ocse/linker_ocse.ld</code>) and shares no code with the running system (OCOS) or the recovery environment (OCIRE).</p><h2 id="why-a-dedicated-installer-kernel" tabindex="-1">Why a dedicated installer kernel <a class="header-anchor" href="#why-a-dedicated-installer-kernel" aria-label="Permalink to &quot;Why a dedicated installer kernel&quot;">​</a></h2><p>The install must succeed on a machine with <strong>nothing on it</strong> - no operating system, no drivers, no shell. OCSE therefore carries its own minimal versions of everything it needs:</p><table tabindex="0"><thead><tr><th>Module</th><th>Files</th><th>Responsibility</th></tr></thead><tbody><tr><td>Kernel core</td><td><code>kernel/</code>, <code>boot/</code></td><td>freestanding boot, scheduling of the GUI/input loop</td></tr><tr><td>Screen</td><td><code>screen_fb</code></td><td>framebuffer console + the GUI widget layer</td></tr><tr><td>Input</td><td>keyboard driver</td><td>menu keys, text fields, hotkeys</td></tr><tr><td>Disk access</td><td><code>ocse_disk.c</code>, <code>ocse_atapi.c</code></td><td>ATA/ATAPI and BIOS/UEFI disk I/O</td></tr><tr><td>Partitioning</td><td><code>ocse_part.c</code>, <code>ocse_detect.c</code></td><td>MBR/GPT decode, free-gap detection, existing-system detection</td></tr><tr><td>Filesystems</td><td><code>fs/</code>, <code>ocse_mkfs.c</code>, <code>ocse_ext4w.c</code></td><td>FAT32/exFAT/ext4 create and read/write</td></tr><tr><td>Install payload</td><td><code>ocse_iso.c</code>, <code>ocse_inst.c</code></td><td>ISO9660 read, the install state machine</td></tr><tr><td>Integrity</td><td><code>ocse_sha256.c</code></td><td>SHA-256 digests (media check, password hashing)</td></tr><tr><td>User interface</td><td><code>ocse_gui.c</code>, <code>ocse_wizard.c</code>, <code>ocse_cl.c</code></td><td>the panel, the 9-step wizard, the OCSECL shell</td></tr><tr><td>Localization</td><td><code>ocse_i18n.c</code></td><td>English / Simplified Chinese, live switching</td></tr></tbody></table><h2 id="the-safety-model" tabindex="-1">The safety model <a class="header-anchor" href="#the-safety-model" aria-label="Permalink to &quot;The safety model&quot;">​</a></h2><p>OCSE is deliberately <strong>incapable of damaging an existing Open Cube OS installation by accident</strong>:</p><ul><li>It <strong>refuses</strong> a target that already boots <code>opencube.elf</code> (the existing-system check) - the wizard shows the refusal instead of a partition list.</li><li>Partitioning uses <strong>the largest free gap</strong> on the target disk; it never relocates or deletes foreign partitions to make room.</li><li>Formatting applies <strong>only to the partition OCSE itself created</strong> in the same wizard session.</li><li>Every destructive OCSECL command (<code>mkpart</code>, <code>rmpart</code>, <code>mkfs.*</code>, <code>install</code>, <code>ocbl-install</code>, <code>dd</code>) requires a literal <code>confirm</code> word as its last argument.</li></ul><h2 id="memory-discipline-the-ocsework-zone" tabindex="-1">Memory discipline: the .ocsework zone <a class="header-anchor" href="#memory-discipline-the-ocsework-zone" aria-label="Permalink to &quot;Memory discipline: the .ocsework zone&quot;">​</a></h2><p>All mutable installer state lives in a dedicated <code>.ocsework</code> NOLOAD section - the rest of the image is pure code and const data. The environment is freestanding (no libc, no printf): every text buffer is built with bounded string helpers, and a line that cannot fit is refused with a clear error rather than overflowing (the discipline introduced by the buffer-overflow fix in the wizard&#39;s command builder).</p><h2 id="boot-and-detection" tabindex="-1">Boot and detection <a class="header-anchor" href="#boot-and-detection" aria-label="Permalink to &quot;Boot and detection&quot;">​</a></h2><p>The install media is an ISO9660 volume that carries a one-byte <code>/ocse.marker</code> file - the WP-06 install-media contract. The OCBL boot loader recognizes the marker and lists the media as an OCSE entry in its boot menu. On boot, OCSE runs four hardware checks (<code>hwcheck</code>) and then starts the graphical panel; the OCSECL shell is one hotkey away at any time.</p><h2 id="relationship-to-the-other-components" tabindex="-1">Relationship to the other components <a class="header-anchor" href="#relationship-to-the-other-components" aria-label="Permalink to &quot;Relationship to the other components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Role</th><th>See</th></tr></thead><tbody><tr><td>OCBL</td><td>the boot loader OCSE installs (<code>ocbl-install</code>)</td><td><a href="./../ocbl/">OCBL overview</a></td></tr><tr><td>OCOS</td><td>the system OCSE installs onto the target</td><td>the main manuals</td></tr><tr><td>OCIRE</td><td>the recovery environment, installed on the A/B recovery disk</td><td>the developer handbook</td></tr></tbody></table><p>Next: <a href="./ocse-wizard.html">the 9-step wizard and the OCSECL command dictionary</a>.</p>',15)])])}const u=t(i,[["render",n]]);export{p as __pageData,u as default};
